function sources(){shell(`<span class="eyebrow">Documentación / verificada</span><h1 class="title">Fuentes oficiales del SAS.</h1><p class="lead">Acceso directo a cuadernillos originales y plantillas definitivas utilizados por el simulador.</p><section class="card panel"><div class="heading"><h3>Documentación de exámenes</h3></div>${B.exams.map(e=>`<div class="rowline"><div><b>${escaped(e.name)}</b><small>${escaped(e.note)}</small></div><div class="buttons"><a class="button secondary" href="${e.pdf}" target="_blank" rel="noopener">PDF ↗</a>${e.template?`<a class="button ghost" href="${e.template}" target="_blank" rel="noopener">Plantilla ↗</a>`:''}</div></div>`).join('')}</section><section class="card panel"><div class="heading"><h3>Programa oficial</h3></div><div class="rowline"><b>Temario Técnico/a Especialista en Radiodiagnóstico</b><a class="button secondary" href="${B.temarioURL}" target="_blank" rel="noopener">Abrir ↗</a></div></section>`)}
function library(){let qs=allQuestions(),query=window.__radiosasSearch||'',topic=window.__radiosasTopic||'Todas',filtered=qs.filter(q=>(topic==='Todas'||q.category===topic)&&(!query||`${q.text} ${q.category} ${q.options.join(' ')}`.toLowerCase().includes(query.toLowerCase())));shell(`<span class="eyebrow">Biblioteca / entrenamiento original</span><h1 class="title">Explora tus preguntas.</h1><p class="lead">${qs.length.toLocaleString('es-ES')} preguntas originales e importadas, no cuadernillos oficiales. Busca conceptos, marca favoritos y prepara test a medida.</p><div class="card panel"><div class="controls"><div class="field"><label>Buscar pregunta</label><input id="library-search" placeholder="Ej.: radiación, TC, anatomía…" value="${escaped(query)}"></div><div class="field"><label>Filtrar materia</label><select id="library-topic"><option>Todas</option>${B.themes.map(t=>`<option ${topic===t?'selected':''}>${escaped(t)}</option>`).join('')}</select></div>${btn('Buscar','library-search')}${btn('Test de favoritos','favorites-test','secondary')}</div><p>${filtered.length} resultados · ${data.favorites.length} favoritos guardados</p></div>${filtered.slice(0,100).map(q=>`<section class="card panel library-card"><div class="heading"><span class="eyebrow">${escaped(q.category)}</span><button class="button ghost" data-favorite="${escaped(q.id)}">${data.favorites.includes(q.id)?'♥ Guardada':'♡ Guardar'}</button></div><h3>${escaped(q.text)}</h3><details><summary>Ver solución razonada</summary><p><strong>${ABC[q.answer]}. ${escaped(q.options[q.answer])}</strong></p><p>${escaped(q.explanation)}</p></details></section>`).join('')||'<div class="empty">No hay preguntas que coincidan con el filtro.</div>'}`)}
function planner(){let done=Object.values(data.topicStatuses).filter(v=>v==='Dominado').length,goal=Number(data.dailyGoal)||20,studied=data.attempts.filter(a=>new Date(a.ended).toDateString()===new Date().toDateString()).reduce((n,a)=>n+a.questions.length,0),days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()+i);return d});shell(`<span class="eyebrow">Tu rutina / estudio consciente</span><h1 class="title">Plan de estudio ♥</h1><p class="lead">Un calendario sencillo que guarda tus objetivos en este navegador. No envía notificaciones automáticas.</p><div class="grid4" style="margin-top:20px">${metric('Objetivo diario',goal,'Preguntas al día')}${metric('Hechas hoy',studied,'Preguntas completadas')}${metric('Temas dominados',done+'/49','Marcados en temario')}${metric('Progreso diario',percent(Math.min(goal,studied),goal)+'%','Respecto al objetivo')}</div><div class="card panel"><h3>Configura tu ritmo</h3><div class="controls"><div class="field"><label>Preguntas al día</label><select id="daily-goal">${[10,20,30,40,50,75].map(n=>`<option value="${n}" ${goal===n?'selected':''}>${n} preguntas</option>`).join('')}</select></div>${btn('Empezar sesión de hoy','daily-test')}</div><div class="progress"><div style="width:${percent(Math.min(goal,studied),goal)}%"></div></div></div><div class="card panel"><h3>Próximos siete días</h3><div class="plan-grid">${days.map(d=>{let k=d.toISOString().slice(0,10),val=data.studyPlan[k]||'';return`<label class="plan-day"><strong>${d.toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'short'})}</strong><input data-study-date="${k}" maxlength="100" placeholder="¿Qué vas a estudiar?" value="${escaped(val)}"></label>`}).join('')}</div></div><div class="card panel"><h3>Recomendación personalizada</h3><p>${weakTopicText()}</p><div class="buttons">${btn('Repasar errores','mistakes-test','secondary')}${btn('Ir al temario','goto-temario','ghost')}</div></div>`)}
function weakTopicText(){let stats={};data.attempts.filter(a=>a.kind==='practice').forEach(a=>a.questions.forEach((id,i)=>{let q=allQuestions().find(x=>x.id===id);if(!q||a.answers[i]===null)return;let st=stats[q.category]||(stats[q.category]={total:0,correct:0});st.total++;if(a.answers[i]===a.keys[i])st.correct++}));let ranked=Object.entries(stats).filter(([,v])=>v.total>=2).sort((a,b)=>a[1].correct/a[1].total-b[1].correct/b[1].total);return ranked.length?`Tu materia con menor precisión observada es ${escaped(ranked[0][0])}: ${percent(ranked[0][1].correct,ranked[0][1].total)}% en ${ranked[0][1].total} respuestas. Priorízala en la próxima sesión.`:'Completa al menos dos preguntas de una materia para obtener una recomendación basada en tus resultados.'}
function settings(){shell(`<span class="eyebrow">Preferencias / privacidad</span><h1 class="title">Configuración.</h1><p class="lead">Exporta tu historial, restaura una copia o añade preguntas de entrenamiento propias.</p><section class="card panel"><div class="heading"><h3>Copias de seguridad</h3></div><p>Tus respuestas y estadísticas se guardan en este navegador. No se sincronizan entre iPhone y ordenador de momento.</p><div class="buttons">${btn('↓ Exportar datos JSON','export')}${btn('Eliminar datos locales','reset','danger')}</div><p>Importar una copia exportada anteriormente:</p><input type="file" id="restore" accept="application/json"></section><section class="card panel"><h3>Contador de preguntas</h3><p>Una pregunta pasa a «Usadas» cuando aparece en un test que has iniciado, aunque lo abandones sin contestar. Se cuenta una sola vez, tanto en test rápidos como en test por materia, favoritos y repaso de errores. Los exámenes oficiales que se corrigen mediante PDF no forman parte del banco de entrenamiento.</p>${questionBankCard()}<div class="buttons">${btn('Reiniciar vuelta de preguntas','reset-question-cycle','secondary')}</div><p>Este reinicio pone el contador a cero y renueva el orden de selección, pero no borra tus notas ni los exámenes anteriores.</p></section><section class="card panel"><h3>Actualizaciones sin perder progreso ♥</h3><p>Al ampliar el banco se reconocen las preguntas nuevas por su identificador y se actualizan automáticamente el total y las pendientes. Se conservan notas, exámenes, errores, favoritos y el plan de estudio. Las preguntas añadidas pasan delante en la cola de los test, sin reiniciar la vuelta previa.</p><p><strong>Importante:</strong> los datos solo existen en este navegador y esta dirección web. Antes de actualizar, usa «Exportar datos JSON». Si cambias de dispositivo, restauras una copia o borras los datos de Safari, el progreso podría dejar de estar disponible.</p></section><section class="card panel"><h3>Importar preguntas de entrenamiento</h3><p>Formato JSON: una lista de objetos con <code>text</code>, <code>category</code>, <code>options</code> (4 textos), <code>answer</code> (0 a 3) y <code>explanation</code>. Las preguntas importadas son tuyas, no oficiales.</p><input type="file" id="questions-import" accept="application/json"><p>Preguntas importadas: ${data.custom.length}</p></section><div class="notice">No hay usuarios ni panel de administración protegido en esta primera versión. Evita introducir datos sensibles. Exporta tus resultados antes de borrar el navegador.</div>`)}
// Laboratorio RX: módulo independiente, sin alterar el motor de test de 5.000 preguntas.
const LAB=window.RADIOSAS_LAB;
let labSession=null;
function labData(){if(!Array.isArray(data.labAttempts))data.labAttempts=[];if(!Array.isArray(data.labSeen))data.labSeen=[];}
function labNew(mode){
 const spots=LAB.spots.map(q=>q.id);
 let order=mode==='exam'?shuffleQuestions(spots):spots;
 labSession={mode,order,index:0,answers:{},hint:false,lightsOn:true,started:Date.now()};
 labData();data.labDraft=mode==='exam'?labSession:null;save();labPage();
}
function labActive(){
 labData();
 if(labSession)return labSession;
 let d=data.labDraft;
 if(d&&d.mode==='exam'&&Array.isArray(d.order)&&d.order.length===LAB.spots.length&&d.order.every(id=>LAB.spots.some(s=>s.id===id))){
  labSession=d;
 } else labSession={mode:'study',order:LAB.spots.map(s=>s.id),index:0,answers:{},hint:false,lightsOn:true,started:Date.now()};
 return labSession;
}
function labCurrent(){let s=labActive();return LAB.spots.find(p=>p.id===s.order[s.index]);}
function labPickAt(x,y){
 const s=labActive(),q=labCurrent();if(!q||s.mode==='results'||!s.lightsOn)return;
 const ordered=LAB.spots.map(z=>({id:z.id,d:Math.hypot(x-z.x,y-z.y),r:z.r})).sort((a,b)=>a.d-b.d);
 const candidate=ordered[0];
 const answer=candidate&&candidate.d<=candidate.r?candidate.id:null;
 s.answers[q.id]={id:answer,x:Math.round(x),y:Math.round(y)};
 if(!data.labSeen.includes(q.id))data.labSeen.push(q.id);
 if(s.mode==='exam')data.labDraft=s;
 save();labRefresh();
}
function labResultsSummary(){labData();const items=data.labAttempts,answered=items.reduce((n,x)=>n+x.answered,0),correct=items.reduce((n,x)=>n+x.correct,0);return {sessions:items.length,answered,correct};}
function labFeedback(){
 const s=labActive(),q=labCurrent(),answer=s.answers[q.id];
 if(!answer)return '';
 if(s.mode==='exam')return '<div class="lab-feedback lab-pending" role="status">Punto registrado. Puedes cambiarlo tocando otra zona o seguir.</div>';
 const good=answer.id===q.id;
 return `<div class="lab-feedback ${good?'lab-ok':'lab-bad'}" role="status"><strong>${good?'✓ Correcto':'✕ Vamos a repasarlo'}</strong><p>${escaped(q.explanation)}</p>${good?'':`<small>La zona correcta aparece marcada en turquesa.</small>`}</div>`;
}
function labPlayMarkup(){
 const s=labActive();
 if(s.mode==='results'){
  const r=s.result;
  return `<section class="lab-result" aria-label="Resultado del examen visual"><span class="eyebrow">Examen visual terminado</span><h2>${r.correct} de ${r.questions.length} aciertos</h2><div class="lab-result-number">${percent(r.correct,r.questions.length)}%</div><p>${r.correct} correctas · ${r.wrong} incorrectas · ${r.blank} sin contestar. Resultado guardado en las estadísticas del Laboratorio.</p><div class="lab-results-review">${r.questions.map((id,i)=>{let q=LAB.spots.find(x=>x.id===id),val=r.answers[id]?.id,ok=val===id;return `<div><b class="${ok?'green-text':'red-text'}">${ok?'✓':'✕'}</b><span>${i+1}. ${escaped(q.label)}</span><small>${val?`Marcaste: ${escaped(LAB.spots.find(x=>x.id===val)?.label||'fuera de zona')}`:'En blanco'}${!ok?` · ${escaped(q.explanation)}`:''}</small></div>`}).join('')}</div><div class="buttons">${btn('Volver al modo estudio','lab-start-study')}${btn('Otro examen visual','lab-start-exam','secondary')}</div></section>`;
 }
 const q=labCurrent(),i=s.index,total=s.order.length,ans=s.answers[q.id],good=ans&&ans.id===q.id;
 const showCorrect=s.mode==='study'&&Boolean(ans||s.hint),showPoint=Boolean(ans),on=s.lightsOn;
 return `<div class="lab-workspace"><div class="lab-screen-head"><div><span class="lab-screen-kicker">${s.mode==='exam'?'EXAMEN VISUAL':'MODO ESTUDIO'} · TÓRAX</span><h2>Localiza: <span>${escaped(q.label)}</span></h2></div><div class="lab-screen-counter">${i+1}<span>/${total}</span></div></div><div class="lab-progress" role="progressbar" aria-label="Progreso del laboratorio" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round((i+1)/total*100)}"><span style="width:${(i+1)/total*100}%"></span></div><div class="lab-viewer-wrap ${on?'lab-screen-on':'lab-screen-off'}"><div class="lab-viewer-toolbar"><span class="lab-indicator"><span></span> VISOR RX · PA SIMULADA</span><button type="button" class="lab-power" data-action="lab-power" aria-pressed="${on}">${on?'◉ Encendido':'◯ Apagado'}</button></div><div class="lab-viewer" aria-label="Esquema torácico interactivo"><img src="rx-torax-esquema.svg" width="700" height="850" draggable="false" alt="Esquema anatómico didáctico de tórax frontal. El lado derecho del paciente aparece a la izquierda de la imagen."><svg data-lab-canvas viewBox="0 0 700 850" width="700" height="850" role="img" aria-label="Toca con el dedo la zona anatómica solicitada" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="700" height="850" fill="transparent"/>${showCorrect?`<circle class="lab-correct-circle" cx="${q.x}" cy="${q.y}" r="${q.r}"/><circle cx="${q.x}" cy="${q.y}" r="7" fill="#75f3da"/>`:''}${showPoint?`<circle class="lab-selected-ring ${s.mode==='study'?(good?'lab-point-ok':'lab-point-wrong'):''}" cx="${ans.x}" cy="${ans.y}" r="19"/><path d="M${ans.x-26} ${ans.y}h52M${ans.x} ${ans.y-26}v52" stroke="${s.mode==='study'?(good?'#75f3da':'#ff8da5'):'#ffd17c'}" stroke-width="2.5" opacity=".95"/>`:''}</svg></div><div class="lab-viewer-footer"><span>D = derecha del paciente · I = izquierda</span><span>Esquema educativo · no clínico</span></div></div><div class="lab-viewer-help"><span>👆 Toca la estructura directamente sobre la imagen.</span>${s.mode==='study'?`<button data-action="lab-hint" class="lab-mini-link">${s.hint?'Ocultar pista':'Mostrar pista'}</button>`:''}</div>${labFeedback()}<div class="lab-controls"><button class="button ghost" data-action="lab-prev" ${i===0?'disabled':''}>← Anterior</button>${s.mode==='exam'?`<button class="button ghost" data-action="lab-skip">En blanco</button>`:''}<button class="button" data-action="lab-next">${i===total-1?(s.mode==='exam'?'Finalizar examen':'Volver a empezar'):'Siguiente →'}</button></div><details class="lab-accessible"><summary>Alternativa accesible: responder por nombre</summary><p>Si no puedes tocar con precisión la imagen, selecciona una estructura de la lista. Esta alternativa evalúa el reconocimiento del nombre, no su localización espacial.</p><div class="lab-choice-grid">${LAB.spots.map((z,j)=>`<button class="${ans?.id===z.id?'is-selected':''}" data-lab-choice="${escaped(z.id)}">${j+1}. ${escaped(z.label)}</button>`).join('')}</div></details></div>`;
}
function labRefresh(){const slot=byId('lab-play-area');if(slot)slot.innerHTML=labPlayMarkup();const count=byId('lab-used-count');if(count)count.textContent=String(data.labSeen?.length||0);}
function labPage(){
 const s=labActive(),stat=labResultsSummary();
 shell(`<div class="lab-heading"><div><span class="eyebrow">RADIOSAS · LABORATORIO VISUAL ♥</span><h1 class="title">Laboratorio de Radiología</h1><p class="lead">Aprende señalando estructuras anatómicas en un esquema frontal de tórax, con un visor inspirado en una sala de radiodiagnóstico.</p></div><span class="lab-spark-icon" aria-hidden="true">✳</span></div><div class="lab-dashboard"><div><b>${LAB.spots.length}</b><span>Zonas anatómicas</span></div><div><b id="lab-used-count">${data.labSeen.length}</b><span>Zonas practicadas</span></div><div><b>${stat.sessions}</b><span>Exámenes visuales</span></div><div><b>${stat.answered?percent(stat.correct,stat.answered)+'%':'—'}</b><span>Precisión visual</span></div></div><div class="lab-modes" role="group" aria-label="Modo del laboratorio"><button class="${s.mode==='study'?'active':''}" data-action="lab-start-study"><strong>♡ Estudio guiado</strong><small>Prueba, recibe pistas y aprende</small></button><button class="${s.mode==='exam'?'active':''}" data-action="lab-start-exam"><strong>▤ Examen visual</strong><small>${LAB.spots.length} estructuras · resultado guardado</small></button></div><div id="lab-play-area">${labPlayMarkup()}</div>${labHistory()}<div class="lab-note"><strong>Nota académica</strong><p>Esta primera edición usa una ilustración original orientativa, no una radiografía diagnóstica. Las posiciones son aproximadas. Los ejercicios visuales se guardan por separado y <strong>no alteran el banco de 5.000 preguntas ni las notas de los test tradicionales</strong>. Las futuras radiografías reales requerirán licencia, selección y validación anatómica.</p></div>`);
}
function labFinish(){const s=labActive();if(s.mode!=='exam')return;
 let answered=0,correct=0;for(const id of s.order){let a=s.answers[id];if(a){answered++;if(a.id===id)correct++;}}
 if(answered<s.order.length&&!confirm(`Quedan ${s.order.length-answered} zonas en blanco. ¿Finalizar el examen visual?`))return;
 const result={id:'lab-'+Date.now(),kind:'lab',questions:s.order.slice(),answers:{...s.answers},correct,wrong:answered-correct,blank:s.order.length-answered,answered,ended:Date.now(),elapsed:Date.now()-s.started};
 labData();data.labAttempts.push(result);data.labDraft=null;save();labSession={mode:'results',result};labPage();
}
function labAction(action){
 const s=labActive();
 if(action.startsWith('lab-review-')){const result=data.labAttempts.find(r=>r.id===action.slice(11));if(result){labSession={mode:'results',result};labPage()}return}
 if(action==='lab-start-study'){labNew('study');return}
 if(action==='lab-start-exam'){if(s.mode==='exam'&&Object.keys(s.answers).length&&!confirm('¿Empezar otro examen visual y descartar el actual?'))return;labNew('exam');return}
 if(s.mode==='results')return;
 if(action==='lab-power'){s.lightsOn=!s.lightsOn;labRefresh();return}
 if(action==='lab-hint'){if(s.mode==='study'){s.hint=!s.hint;labRefresh()}return}
 if(action==='lab-prev'){s.index=Math.max(0,s.index-1);s.hint=false;labPersist();labRefresh();return}
 if(action==='lab-skip'){const q=labCurrent();delete s.answers[q.id];labPersist();if(s.index===s.order.length-1)labFinish();else{s.index++;labPersist();labRefresh()}return}
 if(action==='lab-next'){
  if(s.index===s.order.length-1){if(s.mode==='exam'){labFinish();return}s.index=0}else s.index++;
  s.hint=false;labPersist();labRefresh();
 }
}
function labPersist(){const s=labActive();if(s.mode==='exam'){data.labDraft=s;save()}}
function labSelectZone(id){const s=labActive(),q=labCurrent(),spot=LAB.spots.find(z=>z.id===id);if(!spot||!q||s.mode==='results')return;
 const answer={id:spot.id,x:spot.x,y:spot.y};s.answers[q.id]=answer;if(!data.labSeen.includes(q.id))data.labSeen.push(q.id);labPersist();save();labRefresh();}

function labHistory(){return data.labAttempts.length?`<section class="card panel lab-history"><h3>Historial del laboratorio</h3>${data.labAttempts.slice().reverse().map(r=>`<div class="rowline"><span>${date(r.ended)} · ${r.correct}/${r.questions.length} aciertos</span>${btn('Revisar fallos','lab-review-'+r.id,'secondary')}</div>`).join('')}</section>`:''}
function labStatsCard(){
 const stats=labResultsSummary(),last=data.labAttempts?.slice(-1)[0];
 return `<section class="card panel lab-stats-inline"><div class="heading"><h3>Laboratorio de Radiología ✳</h3>${btn('Abrir laboratorio →','goto-laboratorio','secondary')}</div><div class="lab-dashboard lab-dashboard-sub"><div><b>${LAB.spots.length}</b><span>Estructuras</span></div><div><b>${data.labSeen.length}</b><span>Practicadas</span></div><div><b>${stats.sessions}</b><span>Exámenes</span></div><div><b>${stats.answered?percent(stats.correct,stats.answered)+'%':'—'}</b><span>Precisión</span></div></div><p>${last?`Último examen visual: ${last.correct} de ${last.questions.length} respuestas correctas el ${date(last.ended)}.`:'Empieza el laboratorio para registrar tus resultados de anatomía visual.'} Estos datos se muestran por separado de las 5.000 preguntas de entrenamiento.</p></section>`;
}

function render(){if(section==='inicio')home();else if(section==='reales')official();else if(section==='test')configure();else if(section==='simulacros')configure(true);else if(section==='laboratorio')labPage();else if(section==='exam')examPage();else if(section==='resultado')reviewPage();else if(section==='errores')mistakesPage();else if(section==='estadisticas')statsPage();else if(section==='temario')syllabus();else if(section==='fuentes')sources();else if(section==='biblioteca')library();else if(section==='plan')planner();else if(section==='ajustes')settings()}
function navigate(sectionName){section=sectionName;render()}
function clickAction(a){if(a.startsWith('lab-')){labAction(a);return}if(a==='menu'){const open=byId('sidebar')?.classList.toggle('open');document.querySelector?.('.menu-toggle')?.setAttribute('aria-expanded',String(!!open));return}if(a.startsWith('goto-')){navigate(a.slice(5));return}if(a==='quick'){startPractice(10);return}if(a==='daily-test'){startPractice(Number(data.dailyGoal)||20);return}if(a==='favorites-test'){startPractice(75,'Todas',false,data.favorites);return}if(a==='library-search'){window.__radiosasSearch=byId('library-search').value.trim().slice(0,120);window.__radiosasTopic=byId('library-topic').value;library();return}if(a==='launch'){let n=Number(byId('quantity').value),t=byId('subject').value;config={count:n,topic:t};startPractice(n,t);return}if(a==='mistakes-test'){startPractice(40,'Todas',true);return}if(a==='next'||a==='prev'){if(!current)return;current.index=Math.max(0,Math.min(current.questions.length-1,current.index+(a==='next'?1:-1)));data.draft=current;save();render();return}if(a==='mark'){let i=current.marked.indexOf(current.index);i<0?current.marked.push(current.index):current.marked.splice(i,1);data.draft=current;save();render();return}if(a==='pause'){data.draft=current;current=null;save();navigate('inicio');toast('Examen guardado para continuar después');return}if(a==='resume'){if(!data.draft){toast('No hay examen guardado');return}current=data.draft;section='exam';render();return}if(a==='finish'){finish();return}if(a==='export'){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='radiosas-datos-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Copia exportada');return}if(a==='reset-question-cycle'&&confirm('¿Reiniciar el contador de preguntas usadas y el orden de selección? Se conservarán notas, exámenes, favoritos y preguntas importadas.')){data.seenQuestions=[];data.rotations={};save();navigate('inicio');toast('Contador reiniciado; historial conservado');return}if(a==='reset'&&confirm('Se eliminarán todos los resultados y preguntas importadas de este navegador. ¿Continuar?')){labSession=null;data=initial();save();navigate('inicio');toast('Datos locales reiniciados')}}
document.addEventListener('click',event=>{const canvas=event.target.closest?.('[data-lab-canvas]');if(canvas&&typeof canvas.getBoundingClientRect==='function'){const rect=canvas.getBoundingClientRect();if(rect.width&&rect.height){labPickAt((event.clientX-rect.left)*LAB.width/rect.width,(event.clientY-rect.top)*LAB.height/rect.height)}return}let el=event.target.closest('[data-action],[data-nav],[data-pick],[data-jump],[data-review],[data-official],[data-filter],[data-favorite],[data-lab-choice]');if(!el)return;const ds=el.dataset;if(ds.labChoice){labSelectZone(ds.labChoice);return;}if(ds.favorite){let id=ds.favorite;data.favorites=Array.isArray(data.favorites)?data.favorites:[];data.favorites=data.favorites.includes(id)?data.favorites.filter(x=>x!==id):[...data.favorites,id];save();library();return}if(ds.nav){navigate(ds.nav);return}if(ds.action){clickAction(ds.action);return}if(ds.official){startOfficial(Number(ds.official));return}if(ds.pick!==undefined&&current){current.answers[current.index]=Number(ds.pick);data.draft=current;save();render();return}if(ds.jump!==undefined&&current){current.index=Number(ds.jump);data.draft=current;save();render();return}if(ds.review){resultId=ds.review;reviewFilter='todos';section='resultado';render();return}if(ds.filter){reviewFilter=ds.filter;render();return}});
document.addEventListener('change',event=>{let el=event.target;if(el.id==='daily-goal'){data.dailyGoal=Number(el.value);save();planner();return}if(el.dataset.studyDate){data.studyPlan=data.studyPlan||{};data.studyPlan[el.dataset.studyDate]=el.value.slice(0,100);save();return}if(el.dataset.topic){data.topicStatuses[el.dataset.topic]=el.value;save();toast('Estado de tema actualizado')}if(el.id==='restore'){let file=el.files[0];if(!file)return;file.text().then(str=>{try{let item=JSON.parse(str);if(!item||!Array.isArray(item.attempts)||!Array.isArray(item.custom))throw Error('estructura no reconocida');if(!confirm('¿Sustituir los datos actuales por la copia importada?'))return;labSession=null;data=Object.assign(initial(),item);data.favorites=Array.isArray(data.favorites)?data.favorites:[];data.studyPlan=data.studyPlan&&typeof data.studyPlan==='object'?data.studyPlan:{};data.rotations=data.rotations&&typeof data.rotations==='object'&&!Array.isArray(data.rotations)?data.rotations:{};reconcileBank();save();navigate('inicio');toast('Datos restaurados')}catch(err){alert('No se pudo restaurar la copia: '+err.message)}})}if(el.id==='questions-import'){let file=el.files[0];if(!file)return;file.text().then(str=>{try{let rows=JSON.parse(str);if(!Array.isArray(rows)||!rows.length||rows.length>1000)throw Error('Se necesita una lista de 1 a 1000 preguntas');rows.forEach(q=>{if(typeof q.text!=='string'||q.text.length>3000||!Array.isArray(q.options)||q.options.length!==4||q.options.some(v=>typeof v!=='string'||v.length>1000)||!Number.isInteger(q.answer)||q.answer<0||q.answer>3||typeof q.explanation!=='string'||q.explanation.length>3000)throw Error('Formato de pregunta incorrecto')});const ts=Date.now();rows.forEach((q,i)=>data.custom.push({id:'custom-'+ts+'-'+i,category:B.themes.includes(q.category)?q.category:B.themes[0],text:q.text,options:q.options,answer:q.answer,explanation:q.explanation}));reconcileBank(false);save();navigate('test');toast(rows.length+' preguntas importadas')}catch(err){alert('Importación no válida: '+err.message)}})}});
setInterval(()=>{if(section==='exam'&&current){let el=byId('timer');if(el)el.textContent=timer();if(current.limit&&(Date.now()-current.started)/1000>=current.limit){toast('Tiempo agotado. Se corregirá el examen');let ok=window.confirm;window.confirm=()=>true;try{finish()}finally{window.confirm=ok}}}},1000);
reconcileBank();
